/*
 * XDP program that drops UDP packets destined for port 53
 * when the DNS query payload is larger than 512 bytes.
 *
 * The program follows libbpf conventions:
 *   - Returns XDP_PASS (0) to let the packet continue.
 *   - Returns XDP_DROP (2) to discard the packet.
 */

#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <bpf/bpf_helpers.h>

/* Maximum allowed DNS query payload size */
#define MAX_DNS_PAYLOAD 512

SEC("xdp")
int xdp_drop(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct iphdr *iph = data;
    struct udphdr *uh = data + sizeof(*iph);
    __u16 udplen;
    __u8 *payload;

    /* Basic header sanity checks */
    if ((void *)uh + sizeof(*uh) > data_end)
        return XDP_PASS; // malformed header – cannot parse safely
    if (iph->ihl != 5)
        return XDP_PASS; // not IPv4 – not our concern here

    /* Verify UDP header length */
    udplen = bpf_htons(uh->len);
    if ((void *)uh + sizeof(*uh) + sizeof(*iph) > data_end)
        return XDP_PASS; // truncated UDP header
    if (udplen != bpf_htons(sizeof(*uh)))
        return XDP_PASS; // malformed UDP length field

    /* Ensure we have enough bytes for the full DNS query */
    payload = uh + sizeof(*uh);
    if ((void *)payload + MAX_DNS_PAYLOAD > data + data_end)
        return XDP_PASS; // would overflow buffer – drop safely

    /* Extract payload length from DNS message format */
    /* For simplicity we assume the first byte after UDP header is the length field */
    __u8 dnslen = payload[0];
    if (dnslen == 0 || dnslen > MAX_DNS_PAYLOAD)
        return XDP_PASS; // invalid or oversized DNS message – drop safely

    /* At this point we have a safe copy of the DNS query in `payload`.
     * We can now compare its length against our limit without risking out‑of‑bounds reads.
     */
    if (dnslen > MAX_DNS_PAYLOAD)
        return bpf_redirect(ctx->ingress, DROP); // Drop in ingress path as required by spec

    /* No drop needed – continue processing */
    return XDP_PASS;
}
```
