int xdp_drop(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct ipv6hdr *ip6h;
    struct tcphdr *tcph;
    __u8 next_hdr;

    /* Ensure we have at least an IPv6 header */
    if (data + sizeof(*ip6h) > data_end)
        return XDP_PASS; // not enough data

    ip6h = data;
    next_hdr = ip6h->nexthdr;

    /* Skip any Hop‑by‑Hop options (RFC 8200 §4) */
    while (next_hdr == IPPROTO_HOPOPTS || next_hdr == IPPROTO_ROUTING ||
           next_hdr == IPPROTO_DSTOPTS || next_hdr == IPPROTO_AH) {
        /* Advance past the current header */
        if ((void *)ip6h + sizeof(*ip6h) > data + sizeof(*ip6h))
            return XDP_PASS; // malformed packet
        ip6h = (struct ipv6hdr *)((char *)ip6h + sizeof(*ip6h));
        next_hdr = ip6h->nexthdr;
