    /* At this point we are at the TCP header */
    if ((void *)ip6h + sizeof(*ip6h) > data + sizeof(*ip6h))
        return XDP_PASS; // not enough data for TCP header
    tcph = (struct tcphdr *)((char *)ip6h + sizeof(*ip6h));

    /* Check for both SYN and FIN flags set simultaneously */
    if ((tcph->syn && tcph->fin))
        return XDP_DROP; // malicious packet – drop it early

    /* Normal processing continues here … */
    return XDP_PASS;
}

