 * ------------------------------------------------------------------ */
struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 256);
    __type(key, __be64);   /* Destination MAC address */
    __type(value, __u32);  /* Interface index */
} mac_to_if SEC(".maps");

/* ------------------------------------------------------------------
 * 2. Helper function that looks up the target interface for a given
 *    destination MAC address.
 * ------------------------------------------------------------------ */
static __always_inline int lookup_iface(__be64 dst_mac)
{
    __u32 *idx = bpf_map_lookup_elem(&mac_to_if, &dst_mac);
    if (!idx)
        return -1;               /* No entry – drop or fallback */
    return *idx;                /* Return interface index */
}

/* ------------------------------------------------------------------
 * 3. Main eBPF program attached to XDP (receive path). It receives a
 *    packet from `eth0`, extracts its destination MAC, looks up the
 *    target interface in `mac_to_if`, and redirects the packet.
 * ------------------------------------------------------------------ */
SEC("xdp")
int xdp_redirect(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct ethhdr *eth = data;

    /* Ensure we have at least an Ethernet header before dereferencing */
    if (eth + 1 > data_end)
        return XDP_DROP;

    /* Verify Ethernet protocol is IPv4 (0x0800) – other protocols are not handled here */
    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    /* Extract destination MAC address from the Ethernet header */
    struct ethhdr eth2 = {};
    memcpy(&eth2, eth + 1, sizeof(eth2));

    /* Perform MAC‑to‑interface lookup */
    int iface = lookup_iface(eth2.h_dest);

    /* If no mapping exists or lookup fails, fall back to dropping the packet */
    if (iface == -1)
        return XDP_DROP;

    /* Redirect using bpf_* helper – success returns XDP_* value; failure returns negative error code */
    int ret = bpf_redirect(iface);

    /* If ret == XDP_* we have successfully redirected; otherwise drop or continue processing */
    if (ret == XDP_)
        return ret;   /* Successful redirect – packet is now on eth1 */

    return XDP_;       /* Failure – either invalid index or helper error */
}

