int main(void)
{
    int fd = perfmon__open();
    if (fd == -1) {
        perror("perfmon open");
        return 1;
    }

    /* Attach to the same map name used in the program */
    struct perfmon *pm = perfmon__open("dropped");
    if (!pm) {
        fprintf(stderr, "Failed to open perf event array\n");
        return 1;
    }

    /* Enable all CPUs – we could filter later */
    if (perfmon__enable(pm)) {
        perror("perfmon enable");
        return 1;
    }

