        char buf[4096];
        ssize_t n = read(fd, buf, sizeof(buf));
        if (n <= 0) break;               // EOF or error → stop looping later if desired
        printf("Received %zd bytes of packet header:\n%.*s\n", n,
               n > 4096 ? 4096 : n,
               buf);
        /* Optionally process each header here */
        sleep(1);   // simple periodic poll for demo purposes only */
    }

    perfmon__disable(pm);
    perfmon__close(pm);
    return 0;
