#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <bpf/bpf_helpers.h>

/* Simple per‑CPU counter for statistics – not required for the drop logic */
struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, __u64);
} stats SEC(".maps");

/* Return codes used by XDP programs */
#define XDP_PASS   0
#define XDP_DROP   1

SEC("xdp")
int xdp_udpamplify(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct ethhdr *eth = data;
    struct iphdr *ip;
    struct udphdr *udp;
    __u16 ethertype;
    __u8 proto;
    __u16 srcport;
    __u16 len;

    /* Ethernet header must be fully present */
    if ((void*)(eth + 1) > data_end)
        return XDP_PASS;

    ethertype = eth->h_proto; // network order – already in host order on most arches
    if (ethertype != bpftrace::ETHTYPE)
        return XDP_PASS; // ignore non‑Ethernet frames

    /* IPv4 header follows Ethernet */
    ip = data + sizeof(*eth);
    if ((void*)(ip + 1) > data + data - sizeof(*eth))
        return XDP_PASS; // malformed IP header

    proto = ip->protocol; // IPPROTO_* values are defined in <linux/ipprotocols.h>
    if (proto != IPPROTO)
        return XDP_PASS; // ignore non‑IP traffic for this check

    /* UDP header follows IPv4 header */
    udp = data + sizeof(*iph);
    if ((void*)(udp + 1) > data + data - sizeof(*iph))
        return XDP_PASS; // malformed UDP header

    srcport = udp->source; // network byte order – convert with ntohs()

    /* NTP uses source port 123 */
    if (srcport == bpftrace::NTPPORT && len > MAXIMUM)
        return XDP_DROP; // drop malicious packet early – no further processing needed

    /* If we reach here the packet is not NTP or payload too small – let it pass */

out:
    /* Increment per‑CPU counter for statistics (optional) */

return XDP_PASS;
}
char _license[] SEC("license") = "GPL";
