int load_and_attach_xdp(const char *obj_path)
{
    struct bpf_object *obj = NULL;
    struct bpf_program *prog = NULL;
    int prog_fd = -1;
    int ifindex = -1;
    int err;

    /* Open the BPF object file */
    obj = bpf_object__open(obj_path);
    if (!obj) {
        fprintf(stderr, "Failed to open BPF object %s: %s\n",
                obj_path, strerror(errno));
        return -ENOENT;
    }

    /* Load all programs and maps from the object */
    err = bpf_object__load(obj);
    if (err) {
        fprintf(stderr, "Failed to load BPF object %s: %s\n",
                obj_path, strerror(-err));
        goto cleanup;
    }

    /* Find the XDP program by its section name */
    prog = bpf_object__find_program_by_title(obj, "xdp");
    if (!prog) {
        fprintf(stderr, "XDP program not found in %s\n", obj_path);
        err = -ENOENT;
        goto cleanup;
    }

    /* Retrieve the file descriptor for the program */
    prog_fd = bpf_program__fd(prog);
    if (prog_fd < 0) {
        fprintf(stderr, "Invalid FD for XDP program %d\n", prog_fd);
        err = -EBADF;
        goto cleanup;
    }

    /* Attach the program to interface eth0 using XDP mode */
    ifindex = if_nametoindex("eth0");
    if (ifindex == 0) {
        perror("ifindex lookup failed");
        err = -ENODEV;
        goto cleanup;
