    struct iphdr *iph = data + sizeof(*eth);
    if ((void *)iph + sizeof(*iph) > data + sizeof(*eth))
        return XDP_DROP; // malformed IPv4 header

    /* Extract tuple fields */
    u8 proto = iph->protocol;
    u16 src = bpf_ntohs(*(u16 *)&iph->saddr);
    u16 dst = bpf_ntohs(*(u16 *)&iph->daddr);

