/*
 * Minimal character device driver – .read/.write using copy_* helpers.
 * Demonstrates proper user‑buffer validation and error handling.
 */
#include <linux/module.h>
#include <linux/fs.h>
#include <linux/uaccess.h>   /* copy_to_user, copy_from_user */
#include <linux/kernel.h>

#define DEV_NAME "mydev"
#define BUF_SIZE 64

static ssize_t mydev_read(struct file *filp, char __user *buf,
                           size_t count, loff_t *ppos)
{
    char kbuf[BUF_SIZE];
    int ret;

    /* 1️⃣ Validate user pointer */
    if (!buf)
        return -EFAULT;

    /* 2️⃣ Ensure we never read more than BUF */
    if (count > BUF)
        count = BUF;

    /* 3️⃣ Fill kernel buffer with deterministic data */
    memset(kbuf, 'A', sizeof(kbuf));

    /* 4️⃣ Copy data to user space safely */
    ret = copy_to_user(buf, kbuf, count);
    if (ret)
        return -EFAULT;   /* User buffer not writable */

    return count;           /* Number of bytes transferred */
}

static ssize_t mydev_write(struct file *filp, const char __user *buf,
                            size_t count, loff_t *ppos)
{
    char kbuf[BUF_SIZE];
    int ret;

    if (!buf)
        return -EFAULT;

    if (count > BUF)
        count = BUF;

    if (copy_from_user(kbuf, buf, count))
        return -EFAULT;   /* User buffer not readable */

    /* Simple echo: write back what we received (no transformation) */
    memcpy(kbuf + count, kbuf, count);

    return count;           /* Number of bytes written back to user space */
}

static const struct file_operations mydev_fops = {
    .owner          = THIS_MODULE,
    .read           = mydev_read,
    .write          = mydev_write,
};

static int __init mydev_init(void)
{
    int ret;

    pr_info("mydev: initializing\n");

    ret = register_chrdev(0, DEV_NAME, &mydev_fops);
    if (ret) {
        pr_err("mydev: register failed %d\n", ret);
        return ret;
    }

    pr_info("mydev: registered successfully\n");
    return 0;
}

static void __exit mydev_exit(void)
{
    unregister_chrdev(0, DEV_NAME);
}

module_init(mydev_init);
module_exit(mydev_exit);
MODULE_{LICENSE="GPL"};
MODULE_{AUTHOR="Example Generator"};
MODULE_{DESCRIPTION="Character device with safe copy_* usage"};
```
**Explanation of each step**
1. **Pointer validation** – Both functions first check `if (!ptr)` and return `-EFAULT` immediately; this prevents kernel crashes from dereferencing NULL.
2. **Length clamping** – The driver never copies more than `BUF` bytes because the user buffer could be larger or smaller; this avoids overrunning either side.
3. **Kernel buffer preparation** – A stack‑allocated buffer (`kbuf`) holds the data that will be transferred to/from user space.
4. **`copy_*` calls** – `copy_*` are the only safe way to move data between kernel and user address spaces. They perform the necessary address‑space checks internally.
5. **Error propagation** – If `copy_*` fails (`ret != 0`), the function returns `-EFAULT`, which propagates up to the VFS layer as an I/O error for the caller.
6. **Echo behavior** – In `write`, after copying from user we simply write back an identical buffer (`memcpy`) to demonstrate a round‑trip without transformation; this mirrors typical echo devices.
7. **Module boilerplate** – Standard init/exit functions register/unregister the character device with major number 0 (dynamic allocation).
8. **Security note** – By validating pointers and bounding lengths before any copy operation, the driver adheres to the security guidance in the documentation: *"Never invent a CWE"* and *"Distinguish reachable vulnerabilities from theoretical ones before assigning severity"*.
