/*
 * Example: protecting a shared buffer between an interrupt handler (top half)
 * and a bottom‑half workqueue (bottom half).
 *
 * The top half runs in hard‑irq context and **must** use a spinlock because
 * sleeping is prohibited. The bottom half runs in process context and may
 * safely use a mutex.
 */
#include <linux/spinlock.h>
#include <linux/mutex.h>
#include <linux/interrupt.h>
#include <linux/workqueue.h>

/* Shared data structure */
struct shared_buf {
    int data;
    spinlock_t lock;   /* protects data from top‑half */
};

/* Top‑half ISR – runs in hard IRQ context */
static irqreturn_t my_isr(int irq, void *dev_id)
{
    struct shared_buf *sb = dev_id;
    unsigned long flags;

    /* Acquire the spinlock; this is safe because we are in IRQ context */
    spin_lock_irqsave(&sb->lock, flags);
    sb->data = 42;               /* modify protected data */
    spin_unlock_irqrestore(&sb->lock, flags);

    /* Wake up the bottom‑half workqueue if needed */
    schedule_work(&sb->work);
    return IRQ_HANDLED;
}

/* Bottom‑half work function – runs in process context */
static void my_bottom(struct work_struct *work)
{
    struct shared_buf *sb = container_of(work, struct shared_buf, work);
    unsigned long flags;

    /* Use the mutex because we are now in process context */
    mutex_lock(&sb->lock);
    pr_info("Bottom half: data=%d\n", sb->data);
    mutex_unlock(&sb->lock);
}

/* Workqueue initialization */
static DECLARE_WORK(my_work, my_bottom);
static struct shared_buf sb = {
    .data = 0,
};

static int __init mydrv_init(void)
{
    /* Initialise the spinlock before any ISR can run */
    spin_lock_init(&sb.lock);

    /* Register the top‑half ISR with the kernel */
    request_irq(IRQ0, my_isr, IRQF_SHARED, "mydrv", &sb);

    /* Schedule the bottom‑half work immediately after init */
    schedule_work(&mywork);

    return 0;
}
module_init(mydrv_init);
```
**Explanation of correctness**
- **Top‑half**: `spinlock` is used because it never sleeps; `spin_*` primitives are safe in hard‑IRQ context.
- **Bottom‑half**: `mutex` is used because it may sleep (e.g., waiting for memory allocation). The driver must ensure the mutex is initialized before any ISR can acquire it.
- **Lock ordering**: Both primitives protect the same `shared` structure; there is no nested lock acquisition across contexts, so deadlocks cannot arise.
- **Safety guarantees**: In hard‑IRQ context you cannot call `mutex_*` functions; doing so would trigger a kernel BUG or deadlock.
- **Best practice**: Always match the primitive to its execution context (spin for IRQs/NMI, mutex for process/softirq).

