/*
 * udp-log-module.c – Minimal Netfilter UDP logging module
 *
 * This module registers a local‑out hook that prints the source port,
 * destination port and packet length for every outgoing UDP datagram.
 */

#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/netfilter.h>
#include <linux/netfilter_ipv4.h>
#include <linux/netfilter_ipv6.h>
#include <linux/skbuff.h>
#include <linux/udp.h>

/* ------------------------------------------------------------------ */
/* Callback invoked for each outgoing UDP packet                           */
/* ------------------------------------------------------------------ */
static unsigned int udp_log(void *priv,
                             struct sk_buff *skb,
                             const struct nf_hook_state *state)
{
    /* The skb contains the full IP header followed by the UDP header */
    const struct iphdr *iph = ip_hdr(skb);
    const struct udphdr *uh = udp_hdr(skb);
    u16 src = ntohs(uh->source);
    u16 dst = ntohs(uh->dest);
    u32 pktlen = skb->len;

    /* Guard against malformed packets – if we cannot find headers we skip */
    if (!iph || !uh)
        return NF_ACCEPT;

    /* Log using pr_* – this is safe in kernel context and visible via dmesg */
    pr_info("[UDP LOG] src=%u dst=%u len=%u\n", src, dst, pktlen);

    return NF_ACCEPT;   /* Continue normal processing */
}

/* ------------------------------------------------------------------ */
/* nf_hook_ops structure describing the hook                                    */
/* ------------------------------------------------------------------ */
static struct nf_hook_ops udplog4 = {
    .hook     = udp_log,
    .pf       = NFPROTO_IPV4,
    .hooknum  = NF_INET_LOCAL_OUT,
    .priority = NF_IP4HOOK - 1,
};

static struct nf_hook_ops udplog6 = {
    .hook     = udplog,
    .pf       = NFPROTO_IPV6,
    .hooknum  = NF6TNLLOCALOUT,
    .priority = NF6TNLHOOK - 1,
};

/* ------------------------------------------------------------------ */
/* Module init / exit – register / unregister the hooks                     */n/* ------------------------------------------------------------------ */
static int __init udplogmod_init(void)
{
    int ret;

    pr_info("Loading udp-log kernel module\n");

#if IS_ENABLED(CONFIG_IPV6)
    ret = nfprotos[NFPROTOS].register(&udplog6);
#else
    ret = -EOPNOTSUPP;
#endif

#if IS_ENABLED(CONFIG_IPV4)
    ret |= nfprotos[NFPROTOS].register(&udplog4);
#else
    ret |= -EOPNOTSUPP;
#endif

    if (ret) {
        pr_err("Failed to register UDP log hooks (error %d)\n", ret);
        return ret;
    }

#if IS_ENABLED(CONFIG_IPV6)
    ret |= ipv6tables->register(&udplog6);
#else
    ret |= -EOPNOTSUPP;
#endif

#if IS_ENABLED(CONFIG_{IP,IPv6}VMADDR)
   ipv6tables->register(&udplog4);
   ipv6tables->register(&udplog6);
#else
   ipv6tables->unregister(&udplog4);
   ipv6tables->unregister(&udplog6);
   ipv6tables->unregister(&udplog4); /* redundant but safe */
   ipv6tables->unregister(&udplog6); /* redundant but safe */
#endif

    return 0;
}
module_init(udplogmod_init);
