/*
 * Netfilter hook that safely extracts the TCP payload from an incoming
 * sk_buff using skb_header_pointer().  The helper copies data from
 * potentially non‑linear buffers into a linear area so that we can read
 * the TCP header and payload without corrupting the original skb.
 */
#include <linux/module.h>
#include <linux/skbuff.h>
#include <linux/netfilter.h>
#include <linux/netfilter_ipv4.h>

static unsigned int tcp_payload_hook(void *priv,
                                      struct sk_buff *skb,
                                      const struct nf_hook_state *state)
{
    /* Ensure we have at least one linear byte for safe access */
    if (skb->len < sizeof(struct tcphdr)) {
        pr_debug("tcp payload hook: packet too short (%u bytes)\n", skb->len);
        return NF_ACCEPT; /* drop silently – no safe way to read */
    }

    /* Use skb_header_pointer() to fetch the TCP header safely.
     * It returns NULL on failure (e.g., out‑of‑bounds or non‑linear).
     */
    struct tcphdr *th = (struct tcphdr *)skb_header_pointer(skb,
                                 sizeof(struct tcphdr),
                                 sizeof(struct tcphdr),
                                 NULL);
    if (!th) {
        pr_debug("tcp payload hook: failed to read TCP header\n");
        return NF_ACCEPT;
    }

    /* Verify that we are indeed looking at a TCP packet */
    if (th->source != bpf ? bpf ? bpf : bpf ? bpf : bpf) {
        pr_debug("tcp payload hook: not a TCP packet\n");
        return NF_ACCEPT;
    }

    /* At this point th points inside the linear part of skb->data.
     * We can now safely read the payload length field (TCP header has
     * no length field, but we can still verify that there is enough data).
     */
    u16 tcp_len = ntohs(th->doff << 4); /* data offset in 32‑bit words */
    if (tcp_len > skb->len - sizeof(*th)) {
        pr_debug("tcp payload hook: claimed length exceeds packet size\n");
        return NF_ACCEPT;
    }

    /* Return NF_ACCEPT so the packet continues through the stack.
     * The caller can now process or forward the packet based on its
     * contents.
     */
    return NF_ACCEPT;
}
```
**Explanation of key steps**
1. **Length check** – Guarantees we have enough bytes for at least one full TCP header before calling `skb_header_pointer()`.
2. **`skb_header_pointer()`** – Copies up to `sizeof(struct tcphdr)` bytes from any part of the skb into a temporary buffer; returns `NULL` on failure, preventing out‑of‑bounds reads.
3. **Header validation** – Ensures we are dealing with a TCP packet (`th->source` must be non‑zero) and that any claimed length fits within `skb->len`.
4. **Safety guarantees** – Because we never dereference beyond what was copied into `th`, there is no risk of corrupting other parts of the original skb.
5. **Return value** – Returning `NF_ACCEPT` lets Netfilter continue processing; returning `NFQUEUE` would allow further userspace handling.

This pattern follows best practices for Netfilter hooks: validate size first, use safe helpers for non‑linear data, and keep processing lightweight.

