/*
 * netfilter_fragment_check.c – Helper for Netfilter hooks
 *
 * This function implements the rule described in the kernel documentation:
 *   - Drop any packet whose `skb->protocol` is IPv4.
 *   - For IPv4 packets, drop those where the fragment offset field (bits 0‑13 of
 *     `ip_hdr(skb)->frag_off`) is non‑zero.
 *
 * The implementation follows the exact sequence shown in the documentation:
 *   1. Retrieve `skb->protocol`.
 *   2. Verify it equals `ETH_P_IP`.
 *   3. Ensure we have at least an IP header.
 *   4. Check that the packet is not fragmented (`IPF` flag).
 *   5. If fragmented, verify that the fragment offset is zero.
 */
#include <linux/skbuff.h>
#include <linux/ip.h>
#include <linux/errno.h>

/*
 * netfilter_fragment_check – Drop fragmented IPv4 packets safely.
 *
 * @skb: pointer to the skb being processed by a Netfilter hook.
 *
 * Returns:
 *   0 – packet passed (no drop).
 *   -EINVAL – protocol mismatch or malformed skb (should never happen).
 */
static int netfilter_fragment_check(struct sk_buff *skb)
{
    u8 proto;
    struct iphdr ip;

    /* Step 1: read protocol field */
    proto = skb->protocol;
    if (proto != ETH_P_IP) {
        pr_debug("netfilter: non‑IPv4 protocol %u\n", proto);
        return -EINVAL; /* Not an IPv4 packet – let it continue */
    }

    /* Step 2: ensure we have at least an IP header */
    if (skb->len < sizeof(struct iphdr)) {
        pr_debug("netfilter: truncated IP header (%u bytes)\n", skb->len);
        return -EINVAL;
    }

    /* Step 3: extract and validate IP header */
    ip = *(struct iphdr *)ip_hdr(skb);
    if (ip.frag_off & htons(IPF)) {
        pr_debug("netfilter: IPv4 packet marked as fragmented (%u)\n", ip.frag_off);
        return -EINVAL; /* Fragmented packet – do not drop yet */
    }

    /* Step 4: verify offset == 0 (no payload) */
    if (ip.frag_off & htons(IPOFF)) {
