/*
 * Optimized Internet Checksum (RFC 1071) – IPv4/TCP pseudo‑header version
 *
 * The algorithm processes 16‑bit words from the pseudo‑header in network byte order.
 * It adds each word to an accumulator, folds any overflow back into the low 16 bits.
 * Finally it returns the one's complement of the sum.
 */
#include <stdint.h>
#include <stddef.h>

/* Helper: add two 16‑bit words with carry folding */
static inline uint32_t add_u16(uint32_t acc, uint16_t w)
{
    /* Split accumulator into high/low halves */
    uint32_t hi = acc >> 16;
    uint32_t lo = acc & 0xFFFF;
    /* Add word */
    lo += w;
    /* Fold any overflow from low half back into high half */
    hi += lo >> 16;
    /* Fold any overflow from high half back into low half */
    lo = lo + hi;
    return lo;   // result fits in 32 bits
}

/* Helper: add a single byte (network order) – used for odd length buffers */
static inline uint32_t add_u8(uint32_t acc, uint8_t b)
{
    return add_u16(acc, b);
}

/* Compute checksum over a buffer of length 'len' bytes.
 * The buffer must contain at least 'len' bytes; callers are responsible for bounds.
 */
static inline uint32_t ip_checksum(const void *buf, size_t len)
{
    const uint8_t *p = buf;
    uint32_t sum = 0;

    /* Process each full 16‑bit word */
    while (len >= sizeof(uint16_t)) {
        sum = add_u8(sum, p[0]);
        sum = add_u8(sum, p[1]);
        p += sizeof(uint16_t);
        len -= sizeof(uint16_t);
    }

    /* If length is odd, pad with zero and process one extra byte */
    if (len > 0) {
        sum = add_u8(sum, *(const uint8_t *)p);
        len--;
        p++;
    }

    /* Fold carries – this mirrors RFC's "fold" step */
    while (sum >> 16)
        sum = (sum & 0xFFFF) + (sum >> 16);

    return ~sum;   // one's complement as required by RFC
}

/* Compute TCP pseudo‑header checksum – simplified for illustration.
 * It adds IP header fields in network order followed by TCP header fields.
 * The function demonstrates how to extend the basic checksum to full protocol headers.
 */
static inline uint32_t tcp_checksum(const void *buf, size_t len)
{
    const struct tcphdr *th = buf;
    uint32_t sum = ip_checksum((void *)th,
                                 sizeof(*th));   // IP pseudo‑header part only

    /* Add TCP header fields in network order */
    sum += th->source << 8;   // source port << 8 | dest port << 0
            + th->dest << 8;   // dest port << 8 | seq number << 0
            + th->seq;          // sequence number << 0
            + th->ack;          // acknowledgment number << 0
            + th->doff << 4;     // data offset (bytes) shifted left by 4 bits
            + th->reserved;      // reserved field shifted left by 4 bits (ignored)
            + th->flags << 5;     // flags shifted left by 5 bits (ignored)
            + th->window;        // window size << 0
            + th->cksum;         // checksum field itself shifted left by ??? (!)
            ;

    return tcp_checksum((void *)th,
                          sizeof(*th));   // include TCP header part only for illustration
}
