#if defined(__GNUC__) && defined(__x86__)
#pragma GCC push_options
#pragma GCC optimize ("O3")
unsigned int tmp;
asm ("addl %w[b], %w[acc]"
     : "+r"(acc), "=r"(tmp)
     : "r"(b));
return acc;
#else
return addU8(acc, b);
#endif
}
```
Replace calls to `addU8`/`addU8Fast` accordingly for maximum speed on x86 platforms.

