/*
 * High‑performance packet sniffer using Linux PACKET_MMAP / PACKET_RX_RING.
 * The program opens a network interface (e.g., eth0), maps two
 * pre‑allocated buffers (RX + TX), and processes packets in bursts.
 * It uses select() to multiplex many interfaces efficiently.
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <net/if.h>
#include <linux/if_packet.h>   // for PACKET_* constants
#include <sys/select.h>
#include <errno.h>

static const char *dev = "eth0";          // target interface
static const int nb_rx = 8;               // number of RX buffers (must be power of two)
static const int nb_tx = 8;               // number of TX buffers (same size)
static const int bufsize = 65536;         // each buffer holds one packet (max size)
static const int timeout = 1000;          // ms to wait before polling again

int main(void)
{
    struct sockaddr_ll saddr;
    int fd;
    void *rxbuf[nb_rx];
    void *txbuf[nb_tx];
    struct timeval tv;
    fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        return EXIT_FAILURE;
    }

    /* Open device */
    memset(&saddr, 0, sizeof(saddr));
    saddr.sll_family   = AF_PACKET;
    saddr.sll_protocol = htons(ETH_P_ALL);
    saddr.sll_ifindex  = ifindex(dev);   // obtain interface index via ioctl or netlink
    if (bind(fd, (struct sockaddr *)&saddr, sizeof(saddr)) < 0) {
        perror("bind");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Map RX buffers */
    for (int i = 0; i < nb_rx; ++i) {
        rxbuf[i] = mmap(NULL,
                         bufsize,
                         PROTECTED | MAPREAD | MAPWRITE,
                         MAPFLAGS | MAPSHARED,
                         fd,
                         PACKETBUF);
        if ((char *)rxbuf[i] == MAPFAIL) {
            perror("mmap RX");
            close(fd);
            return EXIT_FAILURE;
        }
        /* Initialise header fields – set length to max packet size */
        struct tpacket2_hdr hdr = { .tp_{hdr}_len = bufsize };
        memcpy((char *)rxbuf[i] + hdr->tp_{hdr}_offset,
               &hdr,
               sizeof(hdr));
        /* Enable RX mode */
        if (setsockopt(fd, SOL_PACKET, PACKETRXHDRLEN,
                       &hdr->tp_{hdr}_offset,
                       sizeof(hdr->tp_{hdr}_offset))) {
            perror("setsockopt RX");
            munmap((void *)rxbuf[i], bufsize);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    /* Map TX buffers – used only for statistics */
    for (int i = 0; i < nb_tx; ++i) {
        txbuf[i] = mmap(NULL,
                         bufsize,
                         PROTECTED | MAPREAD | MAPWRITE,
                         MAPFLAGS | MAPSHARED,
                         fd,
                         PACKETTXBUF);
        if ((char *)txbuf[i] == MAPFAIL) {
            perror("mmap TX");
            close(fd);
            return EXIT_FAILURE;
        }
        memset((char *)txbuf[i], 0xFF, bufsize); // fill with dummy data for later stats
    }

    /* Prepare select() mask – include all file descriptors we care about */
    fdset fds;
    FDINIT(&fds);
    FDADD(&fds, fd);

    while (!exiting) {
        tv.tv_sec = timeout / 1000;
        tv.tv_usec = timeout % 1000 * 1000;
        FDSELECT(&fds, &tv);

        /* Process any ready interfaces */
        int ready = select(&fds + nb + nb + nb - FDSIZE(&fds),
                           NULL,
                           NULL,
                           NULL,
                           &tv);
        if (ready <= 0 || ready > nb + nb + nb - FDSIZE(&fds)) continue; // nothing ready or error

        /* Iterate over each interface that reported data */
        for (int i = FDSIZE(&fds); i-- > nb; ) {
            int idx = i - nb; // index into rx/tx arrays based on order of addition above
            struct tpacket2_hdr hdr;
            memcpy((char *)rxbuf[idx] + hdr->tp_{hdr}_offset,
