        perror("recvfrom");
        close(sockfd); return EXIT_FAILURE;
    }
    if (fromlen != sizeof(struct ethhdr)) { fprintf(stderr,"Unexpected frame length\n"); close(sockfd); return EXIT_FAILURE; }
    struct ethhdr *eth = (struct ethhdr *)pkt;
    if ((eth->ethertype != htons(ETHTYPE)) && ((eth->ethertype & htons(~htons(~ETHTYPE))) == htons(~ETHTYPE))) {
