    uint8_t ihl = iph->ihl; // bits [7:4]
    uint8_t total = ihl * sizeof(*iph);
    printf("IPv4 Header Length (%u words): %u bytes\n", ihl, total);
    printf("TCP Header Start Offset: %u bytes\n", total);
    /* Verify that TCP starts after Ethernet */
    if ((total + sizeof(*iph)) > fromlen) {
        fprintf(stderr,"TCP header would run past Ethernet frame\n");
        close(sockfd); return EXIT_FAILURE;
    }
}
