/*
 * raw_socket_bind_to_device.c
 *
 * Demonstrates how to bind a raw socket to a specific network interface
 * using the SO_BINDTODEVICE socket option.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <net/if.h>          // for struct ifreq (Linux)
#include <errno.h>

int main(void) {
    int fd;
    const char *iface = "eth0";   // replace with desired interface name
    struct ifreq ifr;
    int ret;

    /* 1️⃣ Create an AF_PACKET socket */
    fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        return EXIT_FAILURE;
    }

    /* 2️⃣ Prepare the ifreq structure */
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, iface, IFNAMSIZ - 1);

    /* 3️⃣ Set SO_BINDTODEVICE */
    ret = setsockopt(fd, SOL_SOCKET, SO_BINDTODEVICE,
                     &iface, strlen(iface) + 1);
    if (ret == -1) {
        perror("setsockopt SO_BINDTODEVICE");
        close(fd);
        return EXIT_FAILURE;
    }

    /* 4️⃣ Verify that the kernel accepted the binding */
    /* The kernel does not provide a direct query; we can attempt to send a packet.
     * If sendto fails with ENODEV or EPERM, the binding was not applied.
     */
    struct sockaddr dst = { .sa_family = AF_PACKET };
    memset(&dst.sa_data[0], 0x00, ETH_ALEN); // dummy MAC address

    ssize_t sent = sendto(fd,
                         "\x01\x02\x03\x04\x05\x06", 6,
                         MSG_DONTWAIT,
                         (struct sockaddr *)&dst,
                         sizeof(dst));
    if (sent == -1 && errno == ENODEV) {
        fprintf(stderr, "Binding failed: interface %s not present or not up\n", iface);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Socket bound successfully to %s\n", iface);

    /* Clean up */
    close(fd);
    return EXIT_SUCCESS;
}
```
**Explanation of key steps**
- **Socket creation**: `AF_PACKET` is required for raw sockets; `SOCK_RAW` gives us control over link‑layer frames.
