/*
 * validate_ip_header_checksum()
 *
 * Purpose: Verify the IP header checksum of an incoming packet.
 * Returns 0 on success (checksum OK) and non‑zero on failure.
 *
 * The function assumes the packet buffer contains at least
 * sizeof(struct iphdr) bytes and that the network byte order
 * fields have already been converted to host order.
 */
#include <stddef.h>
#include <stdint.h>
#include <string.h>

/* Helper: compute Internet checksum over a buffer */
static uint16_t ip_checksum(const void *buf, size_t len)
{
    const uint16_t *p = buf;
    uint32_t sum = 0;
    size_t i;

    for (i = 0; i + 1 < len; i += 2) {
        /* Add 16‑bit words; if odd byte remains, pad with zero */
        uint16_t word = p[i] + (p[i + 1] << 8);
        sum += word;
    }
    /* Fold carry bits */
    while (sum >> 16)
        sum = (sum & 0xFFFF) + (sum >> 16);
    return ~sum & 0xFFFF;
}

int validate_ip_header_checksum(const void *packet, size_t pktlen)
{
    if (!packet || pktlen < sizeof(struct iphdr)) {
        /* Not enough data – cannot compute checksum */
        return -1; /* error sentinel */
    }

    const struct iphdr *iph = packet;

    /* Compute checksum over the header only */
    uint16_t computed = ip_checksum(&iph->saddr, sizeof(iph->saddr));
    computed += ip_checksum(&iph->daddr, sizeof(iph->daddr));

    /* RFC 791 specifies that the checksum field itself is not included in the calculation */
    computed += ip_checksum(&iph->check, sizeof(iph->check));

    /* Compare with transmitted value (network order) */
    if (computed != htons(iph->check)) {
        return -2; /* mismatch – discard packet */
    }

    return 0; /* valid – continue processing */
}
```
**Explanation of key points**
- **Endianness**: The `htons`/`ntohs` helpers are used when comparing against `iph->check`, which is stored in network byte order.
- **Checksum calculation**: The helper `ip_checksum()` follows the standard Internet checksum algorithm: it adds each 16‑bit word, folds overflow bits, and finally returns the one's complement.
- **Error handling**: The function returns distinct negative values for different failure modes (`-1` for insufficient data, `-2` for checksum mismatch), allowing callers to log or count errors appropriately.
- **Performance note**: For high‑throughput paths you might inline this logic or use SIMD‑accelerated implementations, but for most kernel or userspace packet filters a simple loop is sufficient.

