/* Helper: find first occurrence of old_ip in pkt->ip */
static size_t find_ip(const unsigned char *old_ip,
                      const unsigned char *start,
                      const unsigned char *end,
                      const struct in_addr old_ip_val)
{
    size_t i = 0;
    while (i + sizeof(struct in_addr) <= end - start) {
        if (memcmp(&start[i], &old_ip_val, sizeof(struct in_addr)) == 0)
            return i;
        i += sizeof(struct in_addr);
    }
    return 0; // not found
}

int main(void)
{
    /* Example NAT rule: translate src=192.168.1.10 → dst=203.0.113.5 */
    struct in_addr old = { .s_addr = htonl(0xC0A8010A) }; // 192.168.1.10
    struct in_addr new = { .s_addr = htonl(0xC0A8FB55) }; // example public IP
    pkt_t pkt;
    memset(&pkt, 0, sizeof(pkt));

    /* Load raw packet from file into memory */
    FILE *fp = fopen("input", "rb");
    if (!fp) {
        perror("fopen");
        return EXIT_FAILURE;
    }
    fseek(fp, 0L, SEEK_END);
    long len = ftell(fp);
    fseek(fp, 0L, SEEK_SET);
    fread(&pkt, 1, len > sizeof(pkt) ? sizeof(pkt) : len, fp);
    fclose(fp);

    /* Build new packet in a mutable buffer */
    memcpy(&pkt->ip[IPHDRLEN], &new, sizeof(new)); // replace src address only (example)

    /* Verify we have enough space for TCP header after IP header */
    if ((unsigned char *)&pkt->tcp - (unsigned char *)&pkt->ip > len) {
        fprintf(stderr, "Packet too short for TCP header\n");
        return EXIT_FAILURE;
