## Safe Allocation Pattern
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>   // for SIZE_MAX

int main(void) {
    const char *input = "This string is definitely longer than 65535 characters...";
    size_t len = strlen(input);
    /* Detect overflow before casting */
    if (len > SIZE_MAX) {
        fprintf(stderr, "Input too long: %zu bytes\n", len);
        return EXIT_FAILURE;
    }
    /* Use size_t for malloc – no truncation risk */
    char *buf = malloc((size_t)len);
    if (!buf) {
        perror("malloc");
        return EXIT_FAILURE;
    }
    /* ... use buf safely ... */
    free(buf);
    return EXIT_SUCCESS;
}
```
### Why This Fix Works
