/* allocator_wrapper.c */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

/* Simple linked list node for each allocated block */
typedef struct {
    void *ptr;
    size_t size;
    struct node *next;
} node_t;

static node_t *head = NULL;   /* head of the allocation list */
static int leak_detected = 0; /* flag set when any allocation fails */

/* Weak symbols – they will be overridden by the user‑provided library */
void *malloc(size_t size) __attribute__((weak));
void free(void *ptr) __attribute__((weak));

/* Helper to create a new node */
static node_t *new_node(void *ptr, size_t size)
{
    node_t *n = malloc(sizeof(*n));
    if (!n) {
        fprintf(stderr, "malloc failed\n");
        return NULL;
    }
    n->ptr  = ptr;
    n->size = size;
    n->next = head;
    head = n;
    return n;
}

/* Helper to remove a node from the list (used on free) */
static void remove_node(node_t *n)
{
    if (!n) return;
    if (head == n) {
        head = n->next;
        free(n);
        return;
    }
    for (node_t *prev = head; prev; prev = prev->next) {
        if (prev->next == n) {
            prev->next = n->next;
            free(n);
            return;
        }
    }
}

/* Wrapper for malloc – records allocation metadata */
void *mymalloc(size_t size)
{
    void *p = malloc(size);
    if (!p) {
        fprintf(stderr, "Allocation failed: %zu bytes\n", size);
        leak_detected = 1;   /* mark as leaked */
        return NULL;          /* caller must handle NULL */
    }
    /* Store metadata in a global structure for later reporting */
    static struct {
        void *ptr;   /* address of allocation */
        size_t   sz;   /* requested size */
        int      inuse;/* 1 if still allocated, 0 after free */
        char     name[64]; /* optional identifier supplied by caller */
    } meta[1024];

    static int idx = 0;
    meta[idx].ptr  = p;
    meta[idx].sz   = size;
    meta[idx].inuse= 1;

#ifdef DEBUG
if (meta[idx].name)
  fprintf(stderr, "[%d] %p (%zu bytes)\n", idx+1, p, size);
else
  fprintf(stderr, "[%d] %p (%zu bytes)\n", idx+1, p, size);
#endif

#ifdef DEBUG
if (meta[idx].name && strcmp(meta[idx].name,"")==0)
  fprintf(stderr,"[%d] %p (%zu bytes)\n",idx+1,p,(size));
#endif

idx++;
return p;   /* caller must eventually call myfree() on this pointer */
}

/* Wrapper for free – validates arguments before removal */
void myfree(void *ptr)
{
#ifdef DEBUG
if (!ptr) {
fprintf(stderr,"myfree called with NULL pointer\n");
return;}
#endif
if (!ptr || !head || !head->inuse || head != ptr) {
fprintf(stderr,"Invalid free: %p\n", ptr);
return;}
remove_node((node_t *)ptr);   /* cast away constness safely here because we are in same translation unit */
}

/* Simple leak detection routine – called from main() or at exit point.
