*/
static void report_leaks()
{
#ifdef DEBUG
printf("=== Memory Leak Report ===\n");
for (int i=0;i<idx;i++) {
printf("[%d] %p (%zu bytes)\n",i+1,(void*)meta[i].ptr,(size));
}
