static void *resource = NULL;

/* Thread‑safe lazy initialization */
void init_resource(void) {
    /* Attempt to set initialized from 0 → 1 */
    int expected = 0;
    if (atomic_compare_exchange_strong(&initialized, &expected, 1)) {
        /* We successfully performed init() */
        resource = init();
        /* No further action needed; other threads will see value == 1 */
    } else {
        /* Another thread already initialized; just return */
        return;
    }
}
```
