    size_t bufsize = PASSWORD_MAX + 1;               // +1 for NUL terminator
    void *buf = mmap(NULL, bufsize,
                     PROT_READ | PROT_WRITE,
                     MAP_PRIVATE | MAP_ANONYMOUS,
                     -1, 0);
    if (buf == MAP_FAILED) {
        perror("mmap");
        return EXIT_FAILURE;
    }

    /* 2️⃣ Fill the buffer with 'x' characters – this is just to make the buffer non‑empty */
    memset(buf, 'x', bufsize);

    /* 3️⃣ Read the password from stdin (blocking until Enter) */
    printf("Enter your password: ");
    fflush(stdout);
    if (fgets(buf, bufsize, stdin) == NULL) {
        perror("fgets");
        goto out;
    }

    /* 4️⃣ Zero the buffer **before** unlocking – prevents swapping of residual data */
    explicit_bzero(buf, bufsize);

    /* 5️⃣ Lock the pages so they cannot be swapped out */
    if (mlock(buf, bufsize) != 0) {
        perror("mlock");
        /* If mlock fails we still need to wipe the memory before exiting */
        explicit_bzero(buf, bufsize);
        goto out;
    }

out:
    printf("\nPassword entered successfully.\n");
    return EXIT_SUCCESS;
}
