        char *addr = strtok(line, " \t");
        char *perms = strtok(NULL, " \t");
        if (!addr || !perms) {
            fprintf(stderr, "Malformed map entry: %s\n", line);
            continue;
        }

        /* Extract permission bits – first character is 'p' for private mapping */
        int perm_idx = strcspn(perms, " \t");
        char perm_char = perms[perm_idx];

        /* rwx bits are the first three characters of the permission string */
        int rwx = (perm_char == 'r') ? 1 : 0;
