/* Simple Shannon entropy calculator for binary data */
static double shannon_entropy(const unsigned char *buf, size_t len) {
    double freq[256] = {0};
    double sum = 0.0;
    size_t i;

    for (i = 0; i < len; ++i) {
        freq[buf[i]]++;
        sum += freq[buf[i]];
    }

    if (sum == 0) return 0.0; // avoid division by zero

    double entropy = 0.0;
    for (int b = 0; b < 256; ++b) {
        if (freq[b] == 0) continue; // ignore zero-frequency symbols
        double p = (double)freq[b] / sum;
        entropy -= p * log2(p);
    }
    return entropy;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <binary_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(argv[1], "rb");
    if (!fp) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    rewind(fp);

    unsigned char *buf = malloc((size_t)file_size);
    if (!buf) {
        perror("malloc");
        fclose(fp);
        return EXIT_FAILURE;
    }

    size_t read = fread((void *)buf, 1, file_size, fp);
    fclose(fp);

    if (read != file_size) {
        fprintf(stderr, "Error reading file\n");
        free(buf);
        return EXIT_FAILURE;
    }

    /* Compute entropy over the whole buffer */
    double total_entropy = shannon_entropy(buf, file_size);

    /* Simple heuristic: treat any region with >7 bits/byte as suspicious */
    const size_t suspicious_len = file_size / 8; // approximate threshold for >7 bits/byte after rounding down to whole bytes

    printf("Total Shannon entropy: %.3f bits/byte\n", total_entropy);

    printf("Suspicious region length: %.3f bytes\n", suspicious_len);

    /* Example decision logic – in real code you would decide based on thresholds */
    if (total_entropy > 7.5 && suspicious_len > 16)
        printf("Potential encrypted/packed payload detected.\n");
    else
        printf("No obvious encryption detected.\n");

    free(buf);
}
```
**Explanation**
- The program reads the entire binary into memory (`malloc`).
- It counts how many times each byte value appears (`freq` array).
